    }));

  const table = document.querySelector('table');
  const headers = Array.from(table.querySelectorAll('thead th')).map(th => th.innerText.trim());
  const firstRow = Array.from(table.querySelectorAll('tbody tr')[0].querySelectorAll('td')).map(td => td.innerText.trim());

  return {
    url: window.location.href,
    name,
    bannerStats,
    firstRowHeaderMap: headers.reduce((acc, h, i) => {
      acc[h || `col_${i}`] = firstRow[i];
      return acc;
    }, {})
  };
});
